/// Total of an invoice in cents: the sum of its lines, minus a discount in
/// percent (0 to 100). The discount is rounded to the nearest cent, half up.
pub fn total(lines: &[u64], discount_percent: u64) -> u64 {
    let sum: u64 = lines.iter().sum();
    let discount = sum * discount_percent / 100;
    sum - discount
}

