//! Request limits per plan.

pub enum Plan {
    Free,
    Team,
    Enterprise,
}

/// The HTTP status for a request.
pub fn status_for(plan: Plan, used: u32, token_expired: bool) -> u16 {
    if token_expired {
        return match plan {
            Plan::Enterprise => 401,
            _ => 498,
        };
    }
    if used >= limit(&plan) { 429 } else { 200 }
}

fn limit(plan: &Plan) -> u32 {
    match plan {
        Plan::Free => 100,
        Plan::Team => 5_000,
        Plan::Enterprise => u32::MAX,
    }
}

